/* === PROGRAM DETECTOR & QUERY NORMALIZER === */
const input = $input.first()?.json || {};
const rawMsg = input.customer_message || input.sanitized_message || '';
const cleanMsg = rawMsg.replace(/[\u064B-\u065F\u0670]/g, '').trim();
const msgLower = cleanMsg.toLowerCase();
const isAr = /[\u0600-\u06FF]/.test(rawMsg);
const locale = input.locale || (isAr ? 'ar' : 'en');

// 1. Comparison detection:
const comparisonKw = [
  'فرق', 'الفرق', 'مقارنة', 'مقارنه', 'بينهم', 'difference', 'compare', 'comparison', 'versus', 'vs'
];
const hasComparison = comparisonKw.some(kw => msgLower.includes(kw));

// 2. Explicit DEBI signals:
const debiKw = [
  'debi', 'رواد مصر الرقمية', 'بناة مصر الرقمية', 'رواد مصر', 'ماجستير دولي', 'جامعة اوتاوا', 'جامعة كوينز', 'ottawa', 'queens'
];
const hasDebi = debiKw.some(kw => msgLower.includes(kw));

// 3. Explicit Digilians signals:
const digiliansKw = [
  'digilians', 'الرواد الرقميون', 'رواد رقميون', 'الرواد', 'depi', 'الأكاديمية العسكرية', 'الاكاديمية العسكرية'
];
const hasDigilians = digiliansKw.some(kw => msgLower.includes(kw));

// 4. Generic Initiative / Admission signals:
const initiativeKw = [
  'شروط', 'التقديم', 'تقديم', 'قبول', 'القبول', 'تسجيل', 'التسجيل', 'مسار', 'مسارات', 'تخصص', 'تخصصات',
  'منحة', 'تدريب', 'شهادة', 'مبادرة', 'المبادرة', 'المبادرات',
  'admission', 'requirement', 'requirements', 'apply', 'applying', 'application', 'eligible', 'eligibility',
  'tracks', 'scholarship', 'initiative', 'initiatives'
];
const hasInitiativeTopic = initiativeKw.some(kw => msgLower.includes(kw));

let programScope = 'GENERAL';

if (hasComparison || (hasDebi && hasDigilians)) {
  programScope = 'COMPARISON';
} else if (hasDebi && !hasDigilians) {
  programScope = 'DEBI';
} else if (hasDigilians && !hasDebi) {
  programScope = 'DIGILIANS';
} else if (hasInitiativeTopic) {
  // Query is about initiative topics (admission, tracks, etc.) but didn't state which initiative
  programScope = 'AMBIGUOUS';
} else {
  // General or potentially out-of-scope question
  programScope = 'GENERAL';
}

let programFilter = "program IN ('DIGILIANS', 'COMMON') AND category != 'disambiguation'";
if (programScope === 'DEBI') {
  programFilter = "program IN ('DEBI', 'COMMON') AND category != 'disambiguation'";
} else if (programScope === 'COMPARISON') {
  programFilter = "program IN ('DIGILIANS', 'DEBI', 'COMMON')";
} else if (programScope === 'AMBIGUOUS') {
  programFilter = "category IN ('disambiguation', 'comparison')";
} else if (programScope === 'GENERAL') {
  programFilter = "program IN ('DIGILIANS', 'DEBI', 'COMMON')";
}

const disambiguationPromptAr = "هل تقصد مبادرة الرواد الرقميون (Digilians) أم مبادرة رواد مصر الرقمية (DEBI)؟";
const disambiguationPromptEn = "Do you mean Digital Pioneers Initiative (Digilians) or Digital Egypt Builders Initiative (DEBI)?";
const disambiguationReply = locale === 'ar' ? disambiguationPromptAr : disambiguationPromptEn;

return [{
  json: {
    ...input,
    customer_message: rawMsg,
    cleaned_message: cleanMsg,
    locale: locale,
    program_scope: programScope,
    program_filter: programFilter,
    is_ambiguous: programScope === 'AMBIGUOUS',
    disambiguation_reply: disambiguationReply
  }
}];

/* === FORMAT RAG KNOWLEDGE RESPONSE WITH PROGRAM ISOLATION === */
const results = ($input.first()?.json || []);
const rows = Array.isArray(results) ? results : (results.results || [results]);
const detectorData = $('Program Detector & Query Normalizer').first()?.json || {};
const locale = detectorData.locale || 'ar';
const isAr = locale === 'ar';
const programScope = detectorData.program_scope || 'AMBIGUOUS';
const isAmbiguous = detectorData.is_ambiguous;
const customerMsg = detectorData.customer_message || '';

// 1. Ambiguous Question: Return Disambiguation Prompt Immediately
if (isAmbiguous) {
  return [{
    json: {
      status: 'clarification_required',
      intent_handled: 'faq_query',
      program_scope: 'AMBIGUOUS',
      is_ambiguous: true,
      rag_context: detectorData.disambiguation_reply,
      direct_reply: detectorData.disambiguation_reply,
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 10,
      confidence: 'high',
      confidence_label: 'HIGH',
      retrieval_status: 'clarification_needed',
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: 'passed' }
    }
  }];
}

// 2. Filter relevant rows
const relevant = rows.filter(r => r && r.relevance_score > 0);

function classifyConfidence(score) {
  if (score >= 4) return 'high';
  if (score >= 2) return 'medium';
  if (score >= 1) return 'low';
  return 'none';
}

if (relevant.length > 0) {
  const sorted = [...relevant].sort((a, b) => (b.relevance_score || 0) - (a.relevance_score || 0));
  const top = sorted[0];
  const topScore = top.relevance_score || 0;
  const confidence = classifyConfidence(topScore);

  let context = '';
  if (programScope === 'COMPARISON') {
    const digiliansRows = sorted.filter(r => r.program === 'DIGILIANS');
    const debiRows = sorted.filter(r => r.program === 'DEBI');
    const commonRows = sorted.filter(r => r.program === 'COMMON');

    const formatRows = (list) => list.map(kb => {
      const q = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);
      const a = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
      return `Q: ${q}\nA: ${a}`;
    }).join('\n---\n');

    context = `[PROGRAM: COMMON / COMPARISON]\n${formatRows(commonRows)}\n\n[PROGRAM: DIGILIANS]\n${formatRows(digiliansRows)}\n\n[PROGRAM: DEBI]\n${formatRows(debiRows)}`;
  } else {
    context = sorted.map(kb => {
      const prog = kb.program || programScope;
      const q = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);
      const a = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
      return `[${prog}] سؤال: ${q}\nإجابة: ${a}`;
    }).join('\n---\n');
  }

  const defaultSource = programScope === 'DEBI'
    ? 'مبادرة رواد مصر الرقمية (DEBI)'
    : (programScope === 'DIGILIANS' ? 'مبادرة الرواد الرقميون (Digilians)' : 'وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)');

  return [{
    json: {
      status: 'rag_context_found',
      intent_handled: 'faq_query',
      program_scope: programScope,
      is_ambiguous: false,
      rag_context: context,
      direct_reply: null,
      customer_message: customerMsg,
      locale: locale,
      top_category: top.category || 'general',
      relevance_score: topScore,
      confidence: confidence,
      confidence_label: confidence.toUpperCase(),
      retrieval_status: 'context_found',
      matched_entries: sorted.length,
      top_program: top.program || programScope,
      source_attribution: top.source_attribution || defaultSource,
      validation: { status: 'passed' }
    }
  }];
} else {
  return [{
    json: {
      status: 'no_context',
      intent_handled: 'faq_query',
      program_scope: programScope,
      is_ambiguous: false,
      rag_context: '',
      direct_reply: null,
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0,
      confidence: 'none',
      confidence_label: 'NONE',
      retrieval_status: 'no_context',
      matched_entries: 0,
      validation: { status: 'no_context', reason: 'no_relevant_kb_entry' }
    }
  }];
}

/* === GUARDRAILS & CROSS-PROGRAM LEAKAGE PREVENTION === */
const ragData = $('Format RAG Knowledge Response').first()?.json || {};
const qwenOutput = ($input.first()?.json?.response ? $input.first()?.json : null);
const locale = ragData.locale || 'ar';
const isAr = locale === 'ar';
const programScope = ragData.program_scope || 'COMMON';
const confidence = ragData.confidence || 'none';

// 1. Direct Ambiguity clarification bypass:
if (ragData.is_ambiguous) {
  return [{
    json: {
      status: 'clarification_required',
      intent_handled: 'faq_query',
      program: 'COMMON',
      category: 'disambiguation',
      reply: ragData.direct_reply,
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: 'passed', program_scope: 'AMBIGUOUS' },
      confidence: 'high',
      confidence_label: 'HIGH',
      guardrail_decision: 'disambiguation_prompt'
    }
  }];
}

// 2. Safe fallbacks for out-of-scope queries
const safeFallbackAR = 'شكراً على استفسارك. لا تتوفر معلومات رسمية حول هذا الموضوع في قاعدة المعرفة المعتمدة لدينا. يرجى التواصل مع فريق الدعم الرسمي لمبادرات وزارة الاتصالات عبر البريد الإلكتروني للحصول على مساعدة إضافية.';
const safeFallbackEN = 'Thank you for your inquiry. Official information regarding this topic is not available in our knowledge base. Please contact the official MCIT initiative support team via email for further assistance.';

let finalReply = '';
let guardrailDecision = 'grounded_llm';

if (confidence === 'none' || confidence === 'low') {
  finalReply = isAr ? safeFallbackAR : safeFallbackEN;
  guardrailDecision = 'hard_deflection';
} else {
  finalReply = (qwenOutput && qwenOutput.response && qwenOutput.response.trim()) || ragData.rag_context || (isAr ? safeFallbackAR : safeFallbackEN);

  // Clean markdown bold for WhatsApp
  finalReply = finalReply.replace(/\*\*/g, '*').replace(/^#+\s*/gm, '').trim();

  // 3. Cross-Program Leakage Guardrail:
  if (programScope === 'DEBI') {
    const lower = finalReply.toLowerCase();
    const hasDigiliansLeak = lower.includes('الأكاديمية العسكرية') || lower.includes('الاكاديمية العسكرية') || lower.includes('18 إلى 32') || lower.includes('18-32') || lower.includes('طلاب السنة النهائية') || lower.includes('digilians.gov.eg');
    if (hasDigiliansLeak) {
      finalReply = ragData.rag_context.replace(/\[DEBI\]\s*/g, '').replace(/سؤال:.*?\nإجابة:\s*/g, '').trim();
      guardrailDecision = 'leakage_prevented_fallback';
    }
  } else if (programScope === 'DIGILIANS') {
    const lower = finalReply.toLowerCase();
    const hasDebiLeak = lower.includes('جامعة أوتاوا') || lower.includes('جامعة اوتاوا') || lower.includes('university of ottawa') || lower.includes('queen\'s') || lower.includes('جيد جداً كحد أدنى') || lower.includes('debi.gov.eg') || lower.includes('بناة مصر الرقمية');
    if (hasDebiLeak) {
      finalReply = ragData.rag_context.replace(/\[DIGILIANS\]\s*/g, '').replace(/سؤال:.*?\nإجابة:\s*/g, '').trim();
      guardrailDecision = 'leakage_prevented_fallback';
    }
  }
}

// Determine Source Attribution:
let sourceAttribution = 'مبادرة الرواد الرقميون (Digilians)';
if (programScope === 'DEBI') {
  sourceAttribution = 'مبادرة رواد مصر الرقمية (DEBI)';
} else if (programScope === 'COMPARISON') {
  sourceAttribution = 'مقارنة معتمدة: مبادرة الرواد الرقميون (Digilians) و مبادرة رواد مصر الرقمية (DEBI)';
} else if (confidence === 'none' || confidence === 'low') {
  sourceAttribution = 'دعم وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)';
}

return [{
  json: {
    status: confidence === 'none' || confidence === 'low' ? 'escalation' : 'success',
    intent_handled: 'faq_query',
    program: programScope,
    category: ragData.top_category || 'general',
    reply: finalReply,
    sources: [sourceAttribution],
    validation: {
      status: guardrailDecision === 'grounded_llm' ? 'passed' : guardrailDecision,
      confidence: confidence,
      relevance_score: ragData.relevance_score || 0,
      guardrail_decision: guardrailDecision
    },
    confidence: confidence,
    confidence_label: ragData.confidence_label || 'N/A',
    guardrail_decision: guardrailDecision
  }
}];
